option.value:
-- Migration: Add labeled contact emails to site_settings
-- Purpose: Allow admins to manage multiple contact emails with a role/purpose label

ALTER TABLE site_settings
  ADD COLUMN IF NOT EXISTS contact_emails JSONB DEFAULT '[]'::jsonb;

-- Optional index if you later query the JSON structure in SQL.
-- CREATE INDEX IF NOT EXISTS idx_site_settings_contact_emails ON site_settings USING GIN (contact_emails);

-- Migration: Add enable_private_access boolean to site_settings
-- Purpose: allow toggling the 'Accès Privilège' feature from settings

ALTER TABLE site_settings
  ADD COLUMN IF NOT EXISTS enable_private_access boolean DEFAULT true;

-- Optionally, set to false to disable the feature by default for existing sites:
-- UPDATE site_settings SET enable_private_access = false WHERE id = 1;

import { motion } from "motion/react";
import { Link } from "react-router-dom";
import React, { useState } from "react";
import { useAppContext } from "../context/AppContext";
import { translations } from "../i18n/translations";
import { isPathHidden } from "../lib/hiddenPages";
import { Send, CheckCircle2, Instagram, Facebook, Linkedin, Youtube } from "lucide-react";

export function Footer() {
  const { language, subscribeNewsletter, settings, universes } = useAppContext();
  const t = translations[language];
  const hp = settings.hiddenPages ?? [];
  const [email, setEmail] = useState("");
  const [isSubscribed, setIsSubscribed] = useState(false);

  const handleSubscribe = (e: React.FormEvent) => {
    e.preventDefault();
    if (email) {
      subscribeNewsletter(email);
      setIsSubscribed(true);
      setEmail("");
      setTimeout(() => setIsSubscribed(false), 5000);
    }
  };

  const title = settings.footerTitle || t.footer.title;
  const cta = settings.footerCta || t.footer.cta;
  const phones = settings.phones.filter(Boolean);
  const emailContact = settings.contactEmail || 'contact@casaprivilege.com';
  const socialLinks = settings.socialLinks;

  return (
    <footer className="border-t border-white/5 bg-[#050505] px-4 sm:px-6 pb-[calc(2.5rem+env(safe-area-inset-bottom,0px))] sm:pb-[calc(4rem+env(safe-area-inset-bottom,0px))] pt-16 sm:pt-40 text-white">
      <div className="max-w-[1400px] mx-auto">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-7 sm:gap-20 mb-10 sm:mb-32">
          {/* Brand & Philosophy */}
          <div className="space-y-4 sm:space-y-10">
            <h2 className="text-2xl sm:text-3xl font-serif tracking-tighter text-brand-gold">
               {settings.logoText || "CASA PRIVILEGE"}
            </h2>
            <p className="hidden sm:block text-white/40 text-[11px] leading-[2.2] tracking-widest uppercase font-light max-w-xs italic">
              "L'excellence n'est pas un acte, mais une habitude. Nous créons des moments suspendus pour les âmes les plus exigeantes."
            </p>
            <div className="flex flex-wrap gap-2 sm:gap-3 pt-1 sm:pt-4">
              {socialLinks.instagram.map((url) => (
                <a key={url} href={url} target="_blank" rel="noopener noreferrer" className="p-2 sm:p-3 border border-white/10 rounded-full hover:border-brand-gold hover:text-brand-gold transition-all duration-500">
                  <Instagram size={16} />
                </a>
              ))}
              {socialLinks.linkedin.map((url) => (
                <a key={url} href={url} target="_blank" rel="noopener noreferrer" className="p-2 sm:p-3 border border-white/10 rounded-full hover:border-brand-gold hover:text-brand-gold transition-all duration-500">
                  <Linkedin size={16} />
                </a>
              ))}
              {socialLinks.facebook.map((url) => (
                <a key={url} href={url} target="_blank" rel="noopener noreferrer" className="p-2 sm:p-3 border border-white/10 rounded-full hover:border-brand-gold hover:text-brand-gold transition-all duration-500">
                  <Facebook size={16} />
                </a>
              ))}
              {socialLinks.youtube.map((url) => (
                <a key={url} href={url} target="_blank" rel="noopener noreferrer" className="p-2 sm:p-3 border border-white/10 rounded-full hover:border-brand-gold hover:text-brand-gold transition-all duration-500">
                  <Youtube size={16} />
                </a>
              ))}
            </div>
          </div>

          {/* Universes Navigation */}
          <div className="space-y-4 sm:space-y-10">
            <h4 className="text-[10px] uppercase tracking-[0.4em] font-black text-brand-gold">Les Univers</h4>
            <ul className="grid grid-cols-2 gap-x-3 gap-y-2 sm:block sm:space-y-6">
               {!isPathHidden("/universe", hp) &&
                 universes.slice(0, 5).map((u) => (
                   <li key={u.id}>
                     <Link
                       to={`/universe/${u.id}`}
                       className="text-white/30 hover:text-white transition-colors text-xs uppercase tracking-widest font-light flex items-center gap-4 group"
                     >
                       <span className="w-4 h-px bg-brand-gold/20 group-hover:w-8 transition-all duration-500" />
                       {u.name}
                     </Link>
                   </li>
                 ))}
               {!isPathHidden("/store", hp) && (
                 <li>
                   <Link
                     to="/store"
                     className="text-white/30 hover:text-white transition-colors text-xs uppercase tracking-widest font-light flex items-center gap-4 group"
                   >
                     <span className="w-4 h-px bg-brand-gold/20 group-hover:w-8 transition-all duration-500" />
                     Boutique Exclusive
                   </Link>
                 </li>
               )}
            </ul>
          </div>

          {/* Private Channels */}
          <div className="space-y-4 sm:space-y-10">
            <h4 className="text-[10px] uppercase tracking-[0.4em] font-black text-brand-gold">Salon Privé</h4>
            <div className="space-y-3 sm:space-y-8">
               <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
                  <span className="text-[9px] uppercase tracking-widest text-white/20 font-bold">Contact direct</span>
                  {phones.length > 0 ? (
                    phones.map((p) => (
                      <a key={p} href={`tel:${p.replace(/\s/g, "")}`} className="text-base sm:text-xl font-serif text-white hover:text-brand-gold transition-colors block">
                        {p}
                      </a>
                    ))
                  ) : (
                    <span className="text-base sm:text-xl font-serif text-white/35">+212 5XX XX XX XX</span>
                  )}
               </div>
               <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
                  <span className="text-[9px] uppercase tracking-widest text-white/20 font-bold">Ligne Sécurisée</span>
                  <a href={`mailto:${emailContact}`} className="text-sm sm:text-lg italic font-light text-white/60 hover:text-white transition-colors">{emailContact}</a>
               </div>
               {!isPathHidden("/contact", hp) && (
                 <Link to="/contact">
                   <motion.button
                     whileHover={{ scale: 1.05 }}
                    className="mt-1 sm:mt-4 px-4 sm:px-8 py-2.5 sm:py-4 bg-white text-black text-[8px] sm:text-[10px] font-black uppercase tracking-[0.2em] sm:tracking-[0.3em] hover:bg-brand-gold transition-all duration-500 rounded-sm"
                   >
                     Solliciter le Concierge
                   </motion.button>
                 </Link>
               )}
            </div>
          </div>

          {/* Newsletter / Circle */}
          <div className="space-y-4 sm:space-y-10">
            <h4 className="text-[10px] uppercase tracking-[0.4em] font-black text-brand-gold">Le Cercle</h4>
            <p className="hidden sm:block text-white/40 text-[11px] leading-relaxed tracking-widest uppercase italic">
              Inscrivez-vous pour recevoir nos invitations confidentielles.
            </p>
            <form onSubmit={handleSubscribe} className="relative group">
              <input
                type="email"
                required
                placeholder="VOTRE ADRESSE EMAIL"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-transparent border-b border-white/10 py-3 sm:py-5 text-[10px] sm:text-[11px] tracking-[0.2em] sm:tracking-[0.3em] uppercase focus:outline-none focus:border-brand-gold transition-all placeholder:text-white/10 italic"
              />
              <button
                type="submit"
                className="absolute right-0 top-1/2 -translate-y-1/2 p-1.5 sm:p-2 text-white/20 hover:text-brand-gold transition-colors"
              >
                {isSubscribed ? <CheckCircle2 size={20} className="text-green-500" /> : <Send size={20} strokeWidth={1} />}
              </button>
            </form>
          </div>
        </div>

        <div className="pt-8 sm:pt-16 border-t border-white/5 flex flex-col md:flex-row justify-between items-center gap-6 sm:gap-10">
           <div className="flex flex-col md:flex-row items-center gap-6 sm:gap-12">
              <p className="text-[8px] sm:text-[9px] uppercase tracking-[0.35em] sm:tracking-[0.5em] text-white/20 font-black text-center md:text-left">© {new Date().getFullYear()} {settings.siteName || "Casa Privilege"} • Excellence Sur Mesure</p>
              <div className="flex gap-5 sm:gap-8">
                 {!isPathHidden("/about", hp) && (
                   <Link to="/about" className="text-[9px] uppercase tracking-widest text-white/15 hover:text-white transition-colors">About Us</Link>
                 )}
                 <Link to="/privacy" className="text-[9px] uppercase tracking-widest text-white/15 hover:text-white transition-colors">Privacy</Link>
                 <Link to="/terms" className="text-[9px] uppercase tracking-widest text-white/15 hover:text-white transition-colors">Terms</Link>
              </div>
           </div>

           <div className="flex items-center gap-2 sm:gap-3">
              <div className="w-1.5 h-1.5 bg-green-500 rounded-full shadow-[0_0_8px_rgba(34,197,94,0.3)]" />
              <span className="text-[7px] sm:text-[8px] uppercase tracking-[0.25em] sm:tracking-[0.4em] font-black text-white/20 italic text-center">Global Network Fully Operational</span>
           </div>
        </div>
      </div>
    </footer>
  );
}

import { motion } from "motion/react";
import { Link } from "react-router-dom";
import React, { useState } from "react";
import { useAppContext } from "../context/AppContext";
import { translations } from "../i18n/translations";
import { isPathHidden } from "../lib/hiddenPages";
import { Send, CheckCircle2, Mail, Phone } from "lucide-react";

export function Footer() {
  const { language, subscribeNewsletter, settings } = useAppContext();
  const t = translations[language];
  const hp = settings.hiddenPages ?? [];
  const [email, setEmail] = useState("");
  const [isSubscribed, setIsSubscribed] = useState(false);

  const handleSubscribe = (e: React.FormEvent) => {
    e.preventDefault();
    if (email) {
      subscribeNewsletter(email);
      setIsSubscribed(true);
      setEmail("");
      setTimeout(() => setIsSubscribed(false), 5000);
    }
  };

  const title = settings.footerTitle || t.footer.title;
  const cta = settings.footerCta || t.footer.cta;
  const phones = settings.phones.map((phone) => phone.trim()).filter(Boolean);
  const emailContact = settings.contactEmail.trim() || 'contact@casaprivilege.com';
  const emailContacts = [
    ...(emailContact ? [{ label: language === 'fr' ? 'Email principal' : 'Primary email', email: emailContact }] : []),
    ...(settings.contactEmails ?? []),
  ]
    .map((entry) => ({ label: entry.label.trim() || (language === 'fr' ? 'Contact' : 'Contact'), email: entry.email.trim() }))
    .filter((entry) => entry.email);

  const seenEmails = new Set<string>();
  const uniqueEmailContacts = emailContacts.filter((entry) => {
    const key = `${entry.label.toLowerCase()}::${entry.email.toLowerCase()}`;
    if (seenEmails.has(key)) return false;
    seenEmails.add(key);
    return true;
  });

  // const socialLinks = settings.socialLinks; // removed: social icons section deleted

  return (
    <footer className="relative overflow-hidden border-t border-white/10 bg-[#040404] px-4 pb-[calc(2.5rem+env(safe-area-inset-bottom,0px))] pt-16 text-white sm:px-6 sm:pb-[calc(4rem+env(safe-area-inset-bottom,0px))] sm:pt-24">
      <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_15%_0%,rgba(229,169,58,0.18),transparent_28%),radial-gradient(circle_at_85%_20%,rgba(255,255,255,0.08),transparent_24%),linear-gradient(to_bottom,rgba(255,255,255,0.02),transparent_28%)]" />
      <div className="relative mx-auto max-w-screen-2xl">
        <div className="mb-10 flex flex-col gap-5 border-b border-white/10 pb-10 sm:mb-14 sm:pb-12 lg:flex-row lg:items-end lg:justify-between">
          <div className="max-w-4xl space-y-4">
            <p className="text-[9px] font-black uppercase tracking-[0.45em] text-brand-gold/90">{settings.logoText || "CASA PRIVILEGE"}</p>
            <h2 className="font-serif text-4xl leading-[0.95] tracking-tight text-white sm:text-5xl lg:text-7xl">
              {title}
            </h2>
            <p className="max-w-2xl text-sm leading-relaxed text-white/55 sm:text-base">
              Une signature de conciergerie pensée comme une expérience éditoriale : accès privé, réponses rapides et services pilotés en temps réel depuis l’administration.
            </p>
          </div>

          {!isPathHidden("/contact", hp) && (
            <Link
              to="/contact"
              className="inline-flex min-h-12 items-center justify-center rounded-full border border-brand-gold/35 bg-brand-gold px-6 py-3 text-[10px] font-black uppercase tracking-[0.28em] text-brand-black transition-all duration-500 hover:-translate-y-0.5 hover:bg-white hover:text-black sm:px-8"
            >
              {cta}
            </Link>
          )}
        </div>

        <div className="grid gap-6">
          <motion.section
            initial={{ opacity: 0, y: 18 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, margin: "-120px" }}
            transition={{ duration: 0.9, delay: 0.1 }}
            className="rounded-4xl border border-white/10 bg-white/[0.035] p-6 shadow-[0_30px_80px_-45px_rgba(0,0,0,0.9)] sm:p-8"
          >
            <p className="mb-2 text-[9px] font-black uppercase tracking-[0.35em] text-brand-gold">Contact</p>
            <h3 className="font-serif text-2xl text-white sm:text-3xl">Canaux directs</h3>

            <div className="mt-6 space-y-4">
              <div>
                <p className="mb-3 text-[9px] font-black uppercase tracking-[0.32em] text-white/35">Téléphones</p>
                <div className="space-y-2">
                  {phones.length > 0 ? (
                    phones.map((phone) => (
                      <a
                        key={phone}
                        href={`tel:${phone.replace(/\s/g, "")}`}
                        className="flex items-center justify-between rounded-2xl border border-white/10 bg-black/25 px-4 py-3 text-sm text-white/75 transition-colors hover:border-brand-gold/35 hover:text-brand-gold"
                      >
                        <span>{phone}</span>
                        <Phone size={14} />
                      </a>
                    ))
                  ) : (
                    <div className="rounded-2xl border border-white/10 bg-black/25 px-4 py-3 text-sm text-white/35">
                      +212 5XX XX XX XX
                    </div>
                  )}
                </div>
              </div>

              <div>
                <p className="mb-3 text-[9px] font-black uppercase tracking-[0.32em] text-white/35">Emails</p>
                <div className="space-y-2">
                  {uniqueEmailContacts.map((entry) => (
                    <div key={`${entry.label}-${entry.email}`} className="rounded-2xl border border-white/10 bg-black/25 p-4">
                      <div className="mb-1 flex items-center gap-2 text-[9px] font-black uppercase tracking-[0.28em] text-brand-gold/85">
                        <Mail size={12} />
                        {entry.label}
                      </div>
                      <a href={`mailto:${entry.email}`} className="break-all text-sm text-white/80 transition-colors hover:text-brand-gold">
                        {entry.email}
                      </a>
                    </div>
                  ))}
                </div>
              </div>

              {!isPathHidden("/contact", hp) && (
                <Link
                  to="/contact"
                  className="inline-flex min-h-12 w-full items-center justify-center rounded-full bg-white px-5 py-3 text-[10px] font-black uppercase tracking-[0.26em] text-black transition-colors hover:bg-brand-gold"
                >
                  {cta}
                </Link>
              )}

              <form onSubmit={handleSubscribe} className="mt-2 rounded-3xl border border-white/10 bg-black/30 p-4">
                <p className="mb-3 text-[9px] font-black uppercase tracking-[0.32em] text-brand-gold">Newsletter</p>
                <div className="flex gap-2">
                  <input
                    type="email"
                    required
                    placeholder="VOTRE ADRESSE EMAIL"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="min-h-12 flex-1 rounded-full border border-white/10 bg-transparent px-4 text-[10px] uppercase tracking-[0.22em] text-white placeholder:text-white/20 focus:border-brand-gold focus:outline-none"
                  />
                  <button
                    type="submit"
                    className="inline-flex min-h-12 items-center justify-center rounded-full bg-brand-gold px-4 text-black transition-transform hover:-translate-y-0.5"
                    aria-label={language === 'fr' ? 'S’abonner à la newsletter' : 'Subscribe to newsletter'}
                  >
                    {isSubscribed ? <CheckCircle2 size={18} className="text-green-700" /> : <Send size={18} strokeWidth={1.5} />}
                  </button>
                </div>
              </form>
            </div>
          </motion.section>
        </div>

        <div className="mt-8 flex flex-col gap-4 border-t border-white/10 pt-6 sm:mt-10 sm:flex-row sm:items-center sm:justify-between">
          <p className="text-[8px] font-black uppercase tracking-[0.35em] text-white/25 text-center sm:text-left">
            © {new Date().getFullYear()} {settings.siteName || "Casa Privilege"} • {t.footer.rights}
          </p>

          <div className="flex flex-wrap items-center justify-center gap-3 text-[8px] font-black uppercase tracking-[0.3em] text-white/25 sm:justify-end">
            <span className="inline-flex items-center gap-2 rounded-full border border-emerald-500/20 bg-emerald-500/10 px-3 py-2 text-emerald-300">
              <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 shadow-[0_0_8px_rgba(74,222,128,0.35)]" />
              Réseau actif
            </span>
            <span>{settings.address}</span>
          </div>
        </div>
      </div>
    </footer>
  );
}

import { createContext, useContext, useState, ReactNode, useEffect, useCallback, useMemo, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { universes as initialUniverses, journalPosts as initialJournalPosts } from '../data/content';
import { Language } from '../i18n/translations';
import { supabase } from '../lib/supabase';
import {
  dbRowToSiteSettings,
  siteSettingsToDbRow,
  type SiteSettings,
  type SiteSettingsRow,
} from '../lib/siteSettingsDb';
import { fetchExchangeRates, type Currency, type ExchangeRates, DEFAULT_EXCHANGE_RATES } from '../lib/utils';
import {
  activityToRow,
  dbRowToReservation,
  productToRow,
  reservationInputToDbRow,
  rowToActivity,
  rowToJournalPost,
  rowToOrder,
  rowToProduct,
  rowToSubscriber,
  rowToTestimonial,
  rowToUniverse,
  testimonialToRow,
  universeToRow,
  type ReservationRow,
} from '../lib/tableMappers';

export interface Reservation {
  id: string;
  activity_id: string;
  activity_title: string;
  universe_id: string;
  date: string;
  end_date?: string;
  time: string;
  name: string;
  country?: string;
  phone_code?: string;
  phone?: string;
  email?: string;
  contact: string;
  people_count?: number;
  total_price?: number;
  receipt_base64?: string;
  status: 'pending' | 'confirmed' | 'cancelled';
  channel: 'web' | 'whatsapp';
  message?: string;
  article_id?: string;
  article_title?: string;
  price_type?: 'fixed' | 'per_duration';
  created_at: string;
}

export interface Universe {
  id: string;
  name: string;
  flag: string;
  location: string;
  description: string;
  heroImage: string;
  gallery: string[];
}

export interface Article {
  id: string;
  activityId: string;
  title: string;
  image: string;
  description: string;
  priceType: 'fixed' | 'per_duration';
  price?: number;
  durationUnit?: 'day' | 'night';
  pricePerUnit?: number;
  availabilityCount?: number;
  isFeatured?: boolean;
  featuredDisplayType?: 'card' | 'hero' | 'grid' | 'carousel';
  /** Présent quand l’article est chargé depuis la base (tri, admin). */
  created_at?: string;
  //  Article Hierarchy
  content?: string;
  isReservable?: boolean;
  articleType?: 'standalone' | 'parent' | 'child';
  parentArticleId?: string;
  childArticles?: Article[];
}

export interface Activity {
  id: string;
  universeId: string;
  title: string;
  category: string;
  price: string;
  image: string;
  description: string;
  minAdvanceDays?: number;
  hasArticles?: boolean;
  articleDisplayType?: 'direct' | 'articles_only';
  articles?: Article[];
  isFeatured?: boolean;
  featuredDisplayType?: 'card' | 'hero' | 'grid' | 'carousel';
  featuredOrder?: number;
  featuredImageUrl?: string;
  /** Présent quand l’activité est chargée depuis la base (tri, admin). */
  created_at?: string;
}

export interface Product {
  id: string;
  title: string;
  category: string;
  price: number;
  oldPrice?: number;
  image: string;
  description: string;
  isExclusive?: boolean;
}

export interface JournalPost {
  id: string;
  title: string;
  category: string;
  date: string;
  image: string;
  excerpt: string;
  content: string;
}

export interface Testimonial {
  id: string;
  name: string;
  role: string;
  content: string;
  rating: number;
  image?: string;
  isApproved: boolean;
}

export interface NewsletterSubscriber {
  id: string;
  email: string;
  subscribedAt: string;
}

export type { SiteSettings };

export interface Profile {
  id: string;
  full_name: string;
  email: string;
  role: string;
  avatar_url?: string;
  created_at: string;
}

export interface Ticket {
  id: string;
  user_name: string;
  user_email: string;
  subject: string;
  status: 'open' | 'closed';
  created_at: string;
}

export interface TicketMessage {
  id: string;
  ticket_id: string;
  sender: string;
  content: string;
  created_at: string;
}

export interface GlobalService {
  id: string;
  title: string;
  description: string;
  image: string;
  link: string;
  type?: string; // Categorie: restaurant, shop, activity, etc.
  latitude?: number;
  longitude?: number;
}

export interface Order {
  id: string;
  customer_name: string;
  customer_email: string;
  total: number;
  items: any[];
  receipt_base64?: string;
  user_phone?: string;
  country?: string;
  phone_code?: string;
  status: 'pending' | 'completed' | 'cancelled';
  created_at: string;
}

export type Theme = 'light' | 'dark';

interface AppContextType {
  reservations: Reservation[];
  addReservation: (reservation: Omit<Reservation, 'id' | 'created_at' | 'status'>) => Promise<void>;
  updateReservationStatus: (id: string, status: Reservation['status']) => Promise<void>;
  deleteReservation: (id: string) => Promise<void>;

  orders: Order[];
  addOrder: (order: Omit<Order, 'id' | 'created_at' | 'status'>) => Promise<void>;
  updateOrderStatus: (id: string, status: Order['status']) => Promise<void>;
  deleteOrder: (id: string) => Promise<void>;

  tickets: Ticket[];
  refreshTickets: () => Promise<void>;
  addTicket: (ticket: Omit<Ticket, 'id' | 'created_at' | 'status'>) => Promise<string>;
  updateTicketStatus: (id: string, status: Ticket['status']) => Promise<void>;
  deleteTicket: (id: string) => Promise<void>;

  ticketMessages: TicketMessage[];
  addTicketMessage: (message: Omit<TicketMessage, 'id' | 'created_at'>) => Promise<void>;
  fetchTicketMessages: (ticketId: string) => Promise<TicketMessage[]>;

  universes: Universe[];
  addUniverse: (u: Universe) => void;
  updateUniverse: (u: Universe) => void;
  deleteUniverse: (id: string) => void;

  activities: Activity[];
  addActivity: (a: Activity) => void;
  updateActivity: (a: Activity) => void;
  deleteActivity: (id: string) => void;

  articles: Article[];
  addArticle: (a: Article) => void;
  updateArticle: (a: Article) => void;
  deleteArticle: (id: string) => void;
  getArticlesByActivityId: (activityId: string) => Article[];
  refreshArticles: () => void;

  products: Product[];
  addProduct: (p: Product) => void;
  updateProduct: (p: Product) => void;
  deleteProduct: (id: string) => void;

  journalPosts: JournalPost[];
  addJournalPost: (p: JournalPost) => void;
  updateJournalPost: (p: JournalPost) => void;
  deleteJournalPost: (id: string) => void;

  testimonials: Testimonial[];
  addTestimonial: (t: Omit<Testimonial, 'id' | 'isApproved'>) => void;
  updateTestimonial: (t: Testimonial) => void;
  deleteTestimonial: (id: string) => void;

  globalServices: GlobalService[];
  addGlobalService: (s: GlobalService) => void;
  updateGlobalService: (s: GlobalService) => void;
  deleteGlobalService: (id: string) => void;

  subscribers: NewsletterSubscriber[];
  subscribeNewsletter: (email: string) => Promise<boolean>;
  unsubscribeNewsletter: (id: string) => Promise<void>;
  refreshNewsletterSubscribers: () => Promise<void>;

  settings: SiteSettings;
  updateSettings: (s: SiteSettings) => void;

  currency: Currency;
  setCurrency: (currency: Currency) => void;
  exchangeRates: ExchangeRates;
  refreshExchangeRates: () => Promise<void>;

  searchQuery: string;
  setSearchQuery: (q: string) => void;

  profiles: Profile[];
  deleteProfile: (id: string) => void;

  theme: Theme;
  toggleTheme: () => void;

  language: Language;
  setLanguage: (lang: Language) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);
const APP_CACHE_KEY = 'cp:app-context-cache:v1';
const REMEMBER_WORK_KEY = 'cp:remember-work';

const initUniverses = Object.values(initialUniverses).map(u => ({
  id: u.id, name: u.name, flag: u.flag, location: u.location, description: u.description, heroImage: u.heroImage, gallery: u.gallery
}));

const initActivities: Activity[] = Object.values(initialUniverses).flatMap(u => 
  u.activities.map((a: any) => ({ ...a, universeId: u.id, minAdvanceDays: 0 }))
);

const initProducts: Product[] = [
  {
    id: "p-1",
    title: "Sculpture Harmonie",
    category: "MODERN STATUE",
    price: 8800,
    oldPrice: 11000,
    image: "https://images.unsplash.com/photo-1544413660-299165566b1d?q=80&w=2940&auto=format&fit=crop",
    description: "Sculpture décorative 'Harmonie' représentant une composition artistique tenant une sphère, symbole d'équilibre.",
    isExclusive: true
  },
  {
    id: "p-2",
    title: "Sculpture Equilibre Eternel",
    category: "FUSION RÉSINE ET FIBRE",
    price: 8550,
    oldPrice: 9000,
    image: "https://images.unsplash.com/photo-1554188248-986da1702485?q=80&w=2940&auto=format&fit=crop",
    description: "Fusion de résine et fibre sur socle métallique, symbole d'harmonie et modernité."
  }
];

import { globalServices as initGlobalServices } from '../data/content';

export function AppProvider({ children }: { children: ReactNode }) {
  const location = useLocation();
  const adminDataLoadedRef = useRef(false);

  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [ticketMessages, setTicketMessages] = useState<TicketMessage[]>([]);
  const [universes, setUniverses] = useState<Universe[]>(initUniverses);
  const [activities, setActivities] = useState<Activity[]>(initActivities);
  const [articles, setArticles] = useState<Article[]>([]);
  const [products, setProducts] = useState<Product[]>(initProducts);
  const [journalPosts, setJournalPosts] = useState<JournalPost[]>(initialJournalPosts);
  const [testimonials, setTestimonials] = useState<Testimonial[]>([
    { id: 't-1', name: 'Alexander Rossi', role: 'CEO, Global Tech', content: 'Casa Privilege a transformé ma vision du luxe.', rating: 5, isApproved: true }
  ]);
  const [globalServices, setGlobalServices] = useState<GlobalService[]>(initGlobalServices);
  const [subscribers, setSubscribers] = useState<NewsletterSubscriber[]>([]);
  const [settings, setSettings] = useState<SiteSettings>({
    siteName: 'Casa Privilege',
    contactEmail: 'contact@casaprivilege.com',
    phones: [],
    address: 'Marrakech, Maroc',
    socialLinks: { instagram: [], facebook: [], linkedin: [], youtube: [] },
    heroBackgroundUrl: '',
    heroTitle: '', heroSubtitle: '', heroCta: '', whatsappNumbers: [], logoText: 'CASA PRIVILEGE', footerTitle: '', footerCta: '', blockedDates: [], blockWeekends: false,
    bankName: '',
    bankBeneficiary: 'COMANE EXCELLENCE SARL',
    bankRib: '',
    hiddenPages: [],
    fontStyle: 'original',
    about: {
      title: 'À Propos de Casa Privilege',
      subtitle: 'Une maison dédiée à l’excellence du service privé.',
      story:
        "Casa Privilege accompagne une clientèle exigeante avec un niveau de discrétion, de précision et d’élégance constant dans chaque interaction.",
      mission:
        "Créer des expériences fluides, humaines et mémorables en combinant expertise locale, standards premium et exécution irréprochable.",
      imageUrl: '',
      visibility: {
        showStory: true,
        showMission: true,
        showContactCard: true,
        showSocials: true,
        showInstagram: true,
        showFacebook: true,
        showLinkedin: true,
        showYoutube: true,
      },
    }
  });
  const [settingsRowId, setSettingsRowId] = useState<number | null>(null);
  const [currency, setCurrency] = useState<Currency>('MAD');
  const [exchangeRates, setExchangeRates] = useState<ExchangeRates>(DEFAULT_EXCHANGE_RATES);
  const [searchQuery, setSearchQuery] = useState('');
  const [theme, setTheme] = useState<Theme>('dark');
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [language, setLanguage] = useState<Language>('fr');
  const rememberEnabled = typeof window !== 'undefined' ? localStorage.getItem(REMEMBER_WORK_KEY) !== '0' : true;

  useEffect(() => {
    if (!rememberEnabled) return;
    try {
      const raw = localStorage.getItem(APP_CACHE_KEY);
      if (!raw) return;
      const cached = JSON.parse(raw) as Partial<{
        reservations: Reservation[];
        orders: Order[];
        tickets: Ticket[];
        ticketMessages: TicketMessage[];
        universes: Universe[];
        activities: Activity[];
        articles: Article[];
        products: Product[];
        journalPosts: JournalPost[];
        testimonials: Testimonial[];
        globalServices: GlobalService[];
        subscribers: NewsletterSubscriber[];
        settings: SiteSettings;
        currency: Currency;
        theme: Theme;
        language: Language;
      }>;

      if (Array.isArray(cached.reservations)) setReservations(cached.reservations);
      if (Array.isArray(cached.orders)) setOrders(cached.orders);
      if (Array.isArray(cached.tickets)) setTickets(cached.tickets);
      if (Array.isArray(cached.ticketMessages)) setTicketMessages(cached.ticketMessages);
      if (Array.isArray(cached.universes) && cached.universes.length > 0) setUniverses(cached.universes);
      if (Array.isArray(cached.activities) && cached.activities.length > 0) setActivities(cached.activities);
      if (Array.isArray(cached.articles)) setArticles(cached.articles);
      if (Array.isArray(cached.products) && cached.products.length > 0) setProducts(cached.products);
      if (Array.isArray(cached.journalPosts) && cached.journalPosts.length > 0) setJournalPosts(cached.journalPosts);
      if (Array.isArray(cached.testimonials)) setTestimonials(cached.testimonials);
      if (Array.isArray(cached.globalServices) && cached.globalServices.length > 0) setGlobalServices(cached.globalServices);
      if (Array.isArray(cached.subscribers)) setSubscribers(cached.subscribers);
      if (cached.settings) setSettings(cached.settings);
      if (cached.currency === 'MAD' || cached.currency === 'EUR' || cached.currency === 'USD') setCurrency(cached.currency);
      if (cached.theme === 'light' || cached.theme === 'dark') setTheme(cached.theme);
      if (cached.language === 'fr' || cached.language === 'en') setLanguage(cached.language);
    } catch (e) {
      console.warn('Impossible de restaurer le cache local:', e);
    }
  }, [rememberEnabled]);

  useEffect(() => {
    if (theme === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [theme]);

  useEffect(() => {
    const storedCurrency = localStorage.getItem('currency') as Currency | null;
    if (storedCurrency === 'MAD' || storedCurrency === 'EUR' || storedCurrency === 'USD') {
      setCurrency(storedCurrency);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('currency', currency);
  }, [currency]);

  useEffect(() => {
    if (!rememberEnabled) return;
    try {
      const payload = {
        reservations,
        orders,
        tickets,
        ticketMessages,
        universes,
        activities,
        articles,
        products,
        journalPosts,
        testimonials,
        globalServices,
        subscribers,
        settings,
        currency,
        theme,
        language,
      };
      localStorage.setItem(APP_CACHE_KEY, JSON.stringify(payload));
    } catch (e) {
      console.warn('Impossible de sauvegarder le cache local:', e);
    }
  }, [
    reservations,
    orders,
    tickets,
    ticketMessages,
    universes,
    activities,
    articles,
    products,
    journalPosts,
    testimonials,
    globalServices,
    subscribers,
    settings,
    currency,
    theme,
    language,
    rememberEnabled,
  ]);

  const refreshExchangeRates = useCallback(async () => {
    const rates = await fetchExchangeRates('MAD');
    setExchangeRates(rates);
  }, []);

  useEffect(() => {
    void refreshExchangeRates();
  }, [refreshExchangeRates]);

  useEffect(() => {
    const body = document.body;
    body.classList.remove('font-style-original', 'font-style-playfair', 'font-style-kiona', 'font-style-riona');
    body.classList.add(`font-style-${settings.fontStyle}`);
  }, [settings.fontStyle]);

  /** Données publiques + réglages : chargées une fois au montage (parcours visiteur plus léger). */
  useEffect(() => {
    const loadSiteSettingsAndGlobal = async () => {
      const { data: sData, error: sErr } = await supabase
        .from('site_settings')
        .select('*')
        .order('id', { ascending: false })
        .limit(1)
        .maybeSingle();
      if (sErr) console.warn('[Supabase] site_settings:', sErr.message);
      else if (sData) {
        setSettingsRowId((sData as SiteSettingsRow).id ?? null);
        setSettings((prev) => dbRowToSiteSettings(sData as SiteSettingsRow, prev));
      }

      const { data: gsData, error: gsErr } = await supabase.from('global_services').select('*');
      if (gsErr) console.warn('[Supabase] global_services:', gsErr.message);
      else if (gsData && gsData.length > 0) setGlobalServices(gsData);
    };

    const loadPublicCatalog = async () => {
      const [uRes, aRes, artRes, pRes, jRes, tmRes] = await Promise.all([
        supabase.from('universes').select('*'),
        supabase.from('activities').select('*'),
        supabase.from('articles').select('*'),
        supabase.from('products').select('*'),
        supabase.from('journal_posts').select('*'),
        supabase.from('testimonials').select('*').order('created_at', { ascending: false }),
      ]);

      if (uRes.error) console.warn('[Supabase] universes:', uRes.error.message);
      else if (uRes.data?.length) setUniverses(uRes.data.map((row) => rowToUniverse(row)));

      if (aRes.error) console.warn('[Supabase] activities:', aRes.error.message);
      else if (aRes.data?.length) setActivities(aRes.data.map((row) => rowToActivity(row)));

      if (artRes.error) console.warn('[Supabase] articles:', artRes.error.message);
      else if (artRes.data?.length) {
        const mappedArticles = artRes.data.map((row: any) => {
          const displayType = row.featured_display_type ?? 'card';
          const isValidDisplayType = ['card', 'hero', 'grid', 'carousel'].includes(displayType);
          return {
            id: row.id,
            activityId: row.activity_id,
            title: row.title,
            image: row.image,
            description: row.description,
            priceType: row.price_type,
            price: row.price,
            durationUnit: row.duration_unit,
            pricePerUnit: row.price_per_unit,
            availabilityCount: row.availability_count,
            isFeatured: Boolean(row.is_featured),
            featuredDisplayType: (isValidDisplayType ? displayType : 'card') as 'card' | 'hero' | 'grid' | 'carousel',
            isReservable: Boolean(row.is_reservable),
            articleType: (row.article_type ?? 'standalone') as 'standalone' | 'parent' | 'child',
            parentArticleId: row.parent_article_id ?? undefined,
          };
        });
        setArticles(mappedArticles);
      } else {
        setArticles([]);
      }

      if (pRes.error) console.warn('[Supabase] products:', pRes.error.message);
      else if (pRes.data?.length) setProducts(pRes.data.map((row) => rowToProduct(row)));

      if (jRes.error) console.warn('[Supabase] journal_posts:', jRes.error.message);
      else if (jRes.data?.length) setJournalPosts(jRes.data.map((row) => rowToJournalPost(row)));

      if (tmRes.error) console.warn('[Supabase] testimonials:', tmRes.error.message);
      else if (tmRes.data?.length) setTestimonials(tmRes.data.map((row) => rowToTestimonial(row)));
    };

    void Promise.all([loadSiteSettingsAndGlobal(), loadPublicCatalog()]);
  }, []);

  /** Données admin : réservations, commandes, tickets, newsletter, profils — uniquement si zone /admin utilisée. */
  useEffect(() => {
    if (!location.pathname.startsWith('/admin')) return;
    if (adminDataLoadedRef.current) return;
    adminDataLoadedRef.current = true;

    const loadAdminData = async () => {
      const ordered = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (!ordered.error && ordered.data) {
        setProfiles(ordered.data);
      } else {
        const sortErr = ordered.error?.message ?? '';
        const maybeMissingSortCol =
          /created_at|column|42703|does not exist/i.test(sortErr) || ordered.error?.code === '42703';
        if (maybeMissingSortCol) {
          const plain = await supabase.from('profiles').select('*');
          if (!plain.error && plain.data) setProfiles(plain.data);
          else if (ordered.error) {
            console.warn('[Supabase] profiles indisponible:', ordered.error.message);
          }
        } else if (ordered.error) {
          console.warn(
            '[Supabase] profiles indisponible:',
            ordered.error.message,
            '— exécutez fix_profiles_rls.sql dans Supabase si la table ou les politiques RLS sont en cause.'
          );
        }
      }

      const [rRes, oRes, tRes, nsRes] = await Promise.all([
        supabase.from('reservations').select('*').order('created_at', { ascending: false }),
        supabase.from('orders').select('*').order('created_at', { ascending: false }),
        supabase.from('tickets').select('*').order('created_at', { ascending: false }),
        supabase.from('newsletter_subscribers').select('*').order('subscribed_at', { ascending: false }),
      ]);

      if (rRes.error) console.warn('[Supabase] reservations:', rRes.error.message);
      else if (rRes.data) setReservations(rRes.data.map((row) => dbRowToReservation(row as ReservationRow)));

      if (oRes.error) console.warn('[Supabase] orders:', oRes.error.message);
      else if (oRes.data) setOrders(oRes.data.map((row) => rowToOrder(row)));

      if (tRes.error) console.warn('[Supabase] tickets:', tRes.error.message);
      else if (tRes.data) setTickets(tRes.data as Ticket[]);

      if (nsRes.error) console.warn('[Supabase] newsletter_subscribers:', nsRes.error.message);
      else setSubscribers((nsRes.data ?? []).map((row) => rowToSubscriber(row)));
    };

    void loadAdminData();
  }, [location.pathname]);

  const addReservation = useCallback(async (data: Omit<Reservation, 'id' | 'created_at' | 'status'>) => {
    const id =
      typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
        ? `res-${crypto.randomUUID()}`
        : `res-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
    const row = reservationInputToDbRow(data, id);
    const { data: insertedData, error } = await supabase.from('reservations').insert([row]).select().single();

    if (error) {
      console.error('[Supabase] reservations insert:', error.message, error);
      return;
    }

    if (insertedData) {
      setReservations((prev) => [dbRowToReservation(insertedData as ReservationRow), ...prev]);
    }
  }, []);
  const updateReservationStatus = useCallback(async (id: string, status: Reservation['status']) => {
    setReservations(prev => prev.map(res => res.id === id ? { ...res, status } : res));
    await supabase.from('reservations').update({ status }).eq('id', id);
  }, []);
  const deleteReservation = useCallback(async (id: string) => {
    setReservations(prev => prev.filter(res => res.id !== id));
    await supabase.from('reservations').delete().eq('id', id);
  }, []);

  const addOrder = useCallback(async (data: Omit<Order, 'id' | 'created_at' | 'status'>) => {
    const { data: inserted, error } = await supabase
      .from('orders')
      .insert({
        customer_email: data.customer_email,
        customer_name: data.customer_name ?? null,
        items: data.items,
        total: data.total,
        receipt_base64: data.receipt_base64 ?? null,
        user_phone: data.user_phone ?? null,
        country: data.country ?? null,
        phone_code: data.phone_code ?? null,
        status: 'pending',
      })
      .select()
      .single();

    if (error) {
      console.error('[Supabase] orders insert:', error.message, error);
      return;
    }
    if (inserted) {
      const o = rowToOrder(inserted);
      setOrders((prev) => [o, ...prev]);
    }
  }, []);
  const updateOrderStatus = useCallback(async (id: string, status: Order['status']) => {
    setOrders(prev => prev.map(o => o.id === id ? { ...o, status } : o));
    await supabase.from('orders').update({ status }).eq('id', id);
  }, []);
  const deleteOrder = useCallback(async (id: string) => {
    setOrders(prev => prev.filter(o => o.id !== id));
    await supabase.from('orders').delete().eq('id', id);
  }, []);

  const addTicket = useCallback(async (data: Omit<Ticket, 'id' | 'created_at' | 'status'>): Promise<string> => {
    const id = `tic-${Date.now()}`;
    const newT: Ticket = { ...data, id, status: 'open', created_at: new Date().toISOString() };
    setTickets(prev => [newT, ...prev]);
    await supabase.from('tickets').insert(newT);
    return id;
  }, []);
  const updateTicketStatus = useCallback(async (id: string, status: Ticket['status']) => {
    setTickets(prev => prev.map(t => t.id === id ? { ...t, status } : t));
    await supabase.from('tickets').update({ status }).eq('id', id);
  }, []);
  const deleteTicket = useCallback(async (id: string) => {
    setTickets(prev => prev.filter(t => t.id !== id));
    await supabase.from('tickets').delete().eq('id', id);
  }, []);

  const refreshTickets = useCallback(async () => {
    const { data, error } = await supabase.from('tickets').select('*').order('created_at', { ascending: false });
    if (error) console.warn('[Supabase] tickets refresh:', error.message);
    else if (data) setTickets(data as Ticket[]);
  }, []);

  const addTicketMessage = useCallback(async (data: Omit<TicketMessage, 'id' | 'created_at'>) => {
    const newMsg: TicketMessage = { ...data, id: `msg-${Date.now()}`, created_at: new Date().toISOString() };
    setTicketMessages(prev => [...prev, newMsg]);
    await supabase.from('ticket_messages').insert(newMsg);
  }, []);
  const fetchTicketMessages = useCallback(async (ticketId: string): Promise<TicketMessage[]> => {
    const { data } = await supabase
      .from('ticket_messages')
      .select('*')
      .eq('ticket_id', ticketId)
      .order('created_at', { ascending: true });
    return data || [];
  }, []);

  const addUniverse = useCallback(async (u: Universe) => {
    setUniverses((prev) => [...prev, u]);
    const { error } = await supabase.from('universes').insert(universeToRow(u));
    if (error) console.error('[Supabase] universes insert:', error.message);
  }, []);
  const updateUniverse = useCallback(async (u: Universe) => {
    setUniverses((prev) => prev.map((i) => (i.id === u.id ? u : i)));
    const { error } = await supabase.from('universes').update(universeToRow(u)).eq('id', u.id);
    if (error) console.error('[Supabase] universes update:', error.message);
  }, []);
  const deleteUniverse = useCallback(async (id: string) => {
    setUniverses((prev) => prev.filter((x) => x.id !== id));
    const { error } = await supabase.from('universes').delete().eq('id', id);
    if (error) console.error('[Supabase] universes delete:', error.message);
  }, []);

  const addActivity = useCallback(async (a: Activity) => {
    setActivities((prev) => [...prev, a]);
    const { error } = await supabase.from('activities').insert(activityToRow(a));
    if (error) console.error('[Supabase] activities insert:', error.message);
  }, []);
  const updateActivity = useCallback(async (a: Activity) => {
    setActivities((prev) => prev.map((i) => (i.id === a.id ? a : i)));
    const { error } = await supabase.from('activities').update(activityToRow(a)).eq('id', a.id);
    if (error) console.error('[Supabase] activities update:', error.message);
  }, []);
  const deleteActivity = useCallback(async (id: string) => {
    setActivities((prev) => prev.filter((x) => x.id !== id));
    const { error } = await supabase.from('activities').delete().eq('id', id);
    if (error) console.error('[Supabase] activities delete:', error.message);
  }, []);

  const addArticle = useCallback(async (a: Article) => {
    console.log(' Adding article to database:', a.title);

    const cap255 = (value?: string | null): string | null => {
      if (!value) return null;
      return String(value).slice(0, 255);
    };

    // Evite les URLs signées trop longues pour les colonnes varchar(255)
    const compactImage = (() => {
      if (!a.image) return null;
      const raw = String(a.image);
      if (raw.length <= 255) return raw;
      const withoutQuery = raw.split("?")[0] ?? raw;
      return withoutQuery.length <= 255 ? withoutQuery : withoutQuery.slice(0, 255);
    })();

    const row = {
      id: cap255(a.id) ?? '',
      activity_id: cap255(a.activityId) ?? '',
      title: cap255(a.title) ?? '',
      image: compactImage,
      description: a.description,
      price_type: cap255(a.priceType) ?? 'fixed',
      price: a.price,
      duration_unit: cap255(a.durationUnit),
      price_per_unit: a.pricePerUnit,
      availability_count: a.availabilityCount,
      is_featured: a.isFeatured ?? false,
      featured_display_type: cap255(a.featuredDisplayType ?? 'card') ?? 'card',
      //  Article Hierarchy
      is_reservable: a.isReservable ?? false,
      article_type: cap255(a.articleType ?? 'standalone') ?? 'standalone',
      parent_article_id: a.parentArticleId && a.parentArticleId.trim() !== "" ? cap255(a.parentArticleId) : null,
    };

    console.log(' Inserting row into articles table:', row);
    const { data, error } = await supabase.from('articles').insert([row]).select();

    if (error) {
      console.error('[Supabase] articles insert ERROR:', error.message);
      console.error('[Supabase] Full error details:', error);
      throw new Error(`Failed to save article to database: ${error.message}`);
    }

    console.log('✅ Article successfully saved to database:', data);
    // Mettre à jour l'état local seulement après la sauvegarde réussie
    setArticles((prev) => [...prev, a]);
  }, []);

  const updateArticle = useCallback(async (a: Article) => {
    console.log(' Updating article in database:', a.title);

    const cap255 = (value?: string | null): string | null => {
      if (!value) return null;
      return String(value).slice(0, 255);
    };

    const compactImage = (() => {
      if (!a.image) return null;
      const raw = String(a.image);
      if (raw.length <= 255) return raw;
      const withoutQuery = raw.split("?")[0] ?? raw;
      return withoutQuery.length <= 255 ? withoutQuery : withoutQuery.slice(0, 255);
    })();

    const row = {
      id: cap255(a.id) ?? '',
      activity_id: cap255(a.activityId) ?? '',
      title: cap255(a.title) ?? '',
      image: compactImage,
      description: a.description,
      price_type: cap255(a.priceType) ?? 'fixed',
      price: a.price,
      duration_unit: cap255(a.durationUnit),
      price_per_unit: a.pricePerUnit,
      availability_count: a.availabilityCount,
      is_featured: a.isFeatured ?? false,
      featured_display_type: cap255(a.featuredDisplayType ?? 'card') ?? 'card',
      //  Article Hierarchy
      is_reservable: a.isReservable ?? false,
      article_type: cap255(a.articleType ?? 'standalone') ?? 'standalone',
      parent_article_id: a.parentArticleId && a.parentArticleId.trim() !== "" ? cap255(a.parentArticleId) : null,
    };

    console.log(' Updating row in articles table:', row);
    const { data, error } = await supabase.from('articles').update(row).eq('id', a.id).select();

    if (error) {
      console.error('[Supabase] articles update ERROR:', error.message);
      console.error('[Supabase] Full error details:', error);
      throw new Error(`Failed to update article in database: ${error.message}`);
    }

    console.log('✅ Article successfully updated in database:', data);
    // Mettre à jour l'état local seulement après la sauvegarde réussie
    setArticles((prev) => prev.map((i) => (i.id === a.id ? a : i)));
  }, []);

  const deleteArticle = useCallback(async (id: string) => {
    console.log(' Deleting article from database:', id);

    const { data, error } = await supabase.from('articles').delete().eq('id', id).select();

    if (error) {
      console.error('[Supabase] articles delete ERROR:', error.message);
      console.error('[Supabase] Full error details:', error);
      throw new Error(`Failed to delete article from database: ${error.message}`);
    }

    console.log('✅ Article successfully deleted from database:', data);
    // Mettre à jour l'état local seulement après la suppression réussie
    setArticles((prev) => prev.filter((x) => x.id !== id));
  }, []);

  const refreshArticles = useCallback(async () => {
    console.log(' Refreshing articles from database...');
    const { data, error } = await supabase.from('articles').select('*');

    if (error) {
      console.error('[Supabase] articles refresh ERROR:', error.message);
      throw new Error(`Failed to refresh articles from database: ${error.message}`);
    }

    if (data?.length) {
      const mappedArticles = data.map((row: any) => {
        const displayType = row.featured_display_type ?? 'card';
        const isValidDisplayType = ['card', 'hero', 'grid', 'carousel'].includes(displayType);
        return {
          id: row.id,
          activityId: row.activity_id,
          title: row.title,
          image: row.image,
          description: row.description,
          priceType: row.price_type,
          price: row.price,
          durationUnit: row.duration_unit,
          pricePerUnit: row.price_per_unit,
          availabilityCount: row.availability_count,
          isFeatured: Boolean(row.is_featured),
          featuredDisplayType: (isValidDisplayType ? displayType : 'card') as 'card' | 'hero' | 'grid' | 'carousel',
          isReservable: Boolean(row.is_reservable),
          articleType: (row.article_type ?? 'standalone') as 'standalone' | 'parent' | 'child',
          parentArticleId: row.parent_article_id ?? undefined,
        };
      });
      setArticles(mappedArticles);
      console.log('✅ Articles successfully refreshed from database:', mappedArticles.length, 'articles');
    } else {
      setArticles([]);
      console.log('✅ No articles found in database');
    }
  }, []);

  const getArticlesByActivityId = useCallback(
    (activityId: string) => articles.filter((a) => a.activityId === activityId),
    [articles],
  );

  const addProduct = useCallback(async (p: Product) => {
    setProducts((prev) => [...prev, p]);
    const { error } = await supabase.from('products').insert(productToRow(p));
    if (error) console.error('[Supabase] products insert:', error.message);
  }, []);
  const updateProduct = useCallback(async (p: Product) => {
    setProducts((prev) => prev.map((i) => (i.id === p.id ? p : i)));
    const { error } = await supabase.from('products').update(productToRow(p)).eq('id', p.id);
    if (error) console.error('[Supabase] products update:', error.message);
  }, []);
  const deleteProduct = useCallback(async (id: string) => {
    setProducts((prev) => prev.filter((x) => x.id !== id));
    const { error } = await supabase.from('products').delete().eq('id', id);
    if (error) console.error('[Supabase] products delete:', error.message);
  }, []);

  const addJournalPost = useCallback(async (p: JournalPost) => {
    setJournalPosts((prev) => [...prev, p]);
    await supabase.from('journal_posts').insert(p);
  }, []);
  const updateJournalPost = useCallback(async (p: JournalPost) => {
    setJournalPosts((prev) => prev.map((i) => (i.id === p.id ? p : i)));
    await supabase.from('journal_posts').update(p).eq('id', p.id);
  }, []);
  const deleteJournalPost = useCallback(async (id: string) => {
    setJournalPosts((prev) => prev.filter((p) => p.id !== id));
    await supabase.from('journal_posts').delete().eq('id', id);
  }, []);

  const addGlobalService = useCallback(async (s: GlobalService) => {
    setGlobalServices((prev) => [...prev, s]);
    await supabase.from('global_services').insert(s);
  }, []);
  const updateGlobalService = useCallback(async (s: GlobalService) => {
    setGlobalServices((prev) => prev.map((item) => (item.id === s.id ? s : item)));
    const { error } = await supabase.from('global_services').upsert(s, { onConflict: 'id' });
    if (error) console.error('Error saving service:', error);
  }, []);
  const deleteGlobalService = useCallback(async (id: string) => {
    setGlobalServices((prev) => prev.filter((s) => s.id !== id));
    await supabase.from('global_services').delete().eq('id', id);
  }, []);

  const addTestimonial = useCallback(async (t: Omit<Testimonial, 'id' | 'isApproved'>) => {
    const newT: Testimonial = { ...t, id: `t-${Date.now()}`, isApproved: false };
    setTestimonials((prev) => [newT, ...prev]);
    const { error } = await supabase.from('testimonials').insert(testimonialToRow(newT));
    if (error) console.error('[Supabase] testimonials insert:', error.message);
  }, []);
  const updateTestimonial = useCallback(async (t: Testimonial) => {
    setTestimonials((prev) => prev.map((i) => (i.id === t.id ? t : i)));
    const { error } = await supabase.from('testimonials').update(testimonialToRow(t)).eq('id', t.id);
    if (error) console.error('[Supabase] testimonials update:', error.message);
  }, []);
  const deleteTestimonial = useCallback(async (id: string) => {
    setTestimonials((prev) => prev.filter((t) => t.id !== id));
    await supabase.from('testimonials').delete().eq('id', id);
  }, []);

  const subscribeNewsletter = useCallback(async (email: string): Promise<boolean> => {
    const trimmed = email.trim().toLowerCase();
    if (!trimmed) return false;

    const { data, error } = await supabase.from('newsletter_subscribers').insert({ email: trimmed }).select().single();

    if (error) {
      if (error.code === '23505') return true;
      console.error('[Supabase] newsletter_subscribers insert:', error.message);
      return false;
    }
    if (data) setSubscribers((prev) => [rowToSubscriber(data), ...prev]);
    return true;
  }, []);

  const unsubscribeNewsletter = useCallback(async (id: string) => {
    const { error } = await supabase.from('newsletter_subscribers').delete().eq('id', id);
    if (error) console.error('[Supabase] newsletter_subscribers delete:', error.message);
    setSubscribers((prev) => prev.filter((s) => s.id !== id));
  }, []);

  const refreshNewsletterSubscribers = useCallback(async () => {
    const { data, error } = await supabase
      .from('newsletter_subscribers')
      .select('*')
      .order('subscribed_at', { ascending: false });
    if (error) {
      console.error('[Supabase] newsletter_subscribers refresh:', error.message);
      return;
    }
    setSubscribers((data ?? []).map((row) => rowToSubscriber(row)));
  }, []);

  const updateSettings = useCallback(async (s: SiteSettings) => {
    const rowId = settingsRowId ?? 1;
    const row = siteSettingsToDbRow(s, rowId);
    let { error } = await supabase.from('site_settings').upsert(row, { onConflict: 'id' });

    if (error) {
      const missingColumn = /Could not find the 'block_weekends' column/i.test(error.message);
      if (missingColumn) {
        const retryRow = { ...row };
        delete (retryRow as any).block_weekends;
        console.warn('[Supabase] block_weekends column missing, retrying without it.');
        const retry = await supabase.from('site_settings').upsert(retryRow, { onConflict: 'id' });
        error = retry.error;
      }
    }

    if (error) {
      console.error('[Supabase] site_settings:', error.message, error);
      return;
    }

    setSettings(s);
  }, [settingsRowId]);

  const deleteProfile = useCallback(async (id: string) => {
    await supabase.from('profiles').delete().eq('id', id);
    setProfiles((prev) => prev.filter((p) => p.id !== id));
  }, []);

  const toggleTheme = useCallback(() => setTheme((prev) => (prev === 'light' ? 'dark' : 'light')), []);

  const contextValue = useMemo<AppContextType>(
    () => ({
      reservations,
      addReservation,
      updateReservationStatus,
      deleteReservation,
      orders,
      addOrder,
      updateOrderStatus,
      deleteOrder,
      tickets,
      refreshTickets,
      addTicket,
      updateTicketStatus,
      deleteTicket,
      ticketMessages,
      addTicketMessage,
      fetchTicketMessages,
      universes,
      addUniverse,
      updateUniverse,
      deleteUniverse,
      activities,
      addActivity,
      updateActivity,
      deleteActivity,
      articles,
      addArticle,
      updateArticle,
      deleteArticle,
      getArticlesByActivityId,
      products,
      addProduct,
      updateProduct,
      deleteProduct,
      journalPosts,
      addJournalPost,
      updateJournalPost,
      deleteJournalPost,
      testimonials,
      addTestimonial,
      updateTestimonial,
      deleteTestimonial,
      globalServices,
      addGlobalService,
      updateGlobalService,
      deleteGlobalService,
      subscribers,
      subscribeNewsletter,
      unsubscribeNewsletter,
      refreshNewsletterSubscribers,
      settings,
      updateSettings,
      currency,
      setCurrency,
      exchangeRates,
      refreshExchangeRates,
      refreshArticles,
      searchQuery,
      setSearchQuery,
      profiles,
      deleteProfile,
      theme,
      toggleTheme,
      language,
      setLanguage,
    }),
    [
      reservations,
      addReservation,
      updateReservationStatus,
      deleteReservation,
      orders,
      addOrder,
      updateOrderStatus,
      deleteOrder,
      tickets,
      refreshTickets,
      addTicket,
      updateTicketStatus,
      deleteTicket,
      ticketMessages,
      addTicketMessage,
      fetchTicketMessages,
      universes,
      addUniverse,
      updateUniverse,
      deleteUniverse,
      activities,
      addActivity,
      updateActivity,
      deleteActivity,
      articles,
      addArticle,
      updateArticle,
      deleteArticle,
      getArticlesByActivityId,
      products,
      addProduct,
      updateProduct,
      deleteProduct,
      journalPosts,
      addJournalPost,
      updateJournalPost,
      deleteJournalPost,
      testimonials,
      addTestimonial,
      updateTestimonial,
      deleteTestimonial,
      globalServices,
      addGlobalService,
      updateGlobalService,
      deleteGlobalService,
      subscribers,
      subscribeNewsletter,
      unsubscribeNewsletter,
      refreshNewsletterSubscribers,
      settings,
      updateSettings,
      currency,
      exchangeRates,
      refreshExchangeRates,
      refreshArticles,
      searchQuery,
      profiles,
      deleteProfile,
      theme,
      language,
    ],
  );

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
}

export function useAppContext() {
  const context = useContext(AppContext);
  if (context === undefined) throw new Error('useAppContext must be used within an AppProvider');
  return context;
}

