export interface Reservation {
  id: string;
  activity_id: string;
  activity_title: string;
  universe_id: string;
  date: string;
  end_date?: string;
  time: string;
  name: string;
  country?: string;
  phone_code?: string;
  phone?: string;
  email?: string;
  contact: string;
  people_count?: number;
  total_price?: number;
  receipt_base64?: string;
  status: 'pending' | 'confirmed' | 'cancelled';
  channel: 'web' | 'whatsapp';
  message?: string;
  article_id?: string;
  article_title?: string;
  price_type?: 'fixed' | 'per_duration';
  created_at: string;
}

export interface Universe {
  id: string;
  name: string;
  flag: string;
  location: string;
  description: string;
  heroImage: string;
  gallery: string[];
}

export interface Article {
  id: string;
  activityId: string;
  title: string;
  image: string;
  description: string;
  priceType: 'fixed' | 'per_duration';
  price?: number;
  durationUnit?: 'day' | 'night';
  pricePerUnit?: number;
  availabilityCount?: number;
  isFeatured?: boolean;
  featuredDisplayType?: 'card' | 'hero' | 'grid' | 'carousel';
  /** Présent quand l’article est chargé depuis la base (tri, admin). */
  created_at?: string;
  //  Article Hierarchy
  content?: string;
  isReservable?: boolean;
  articleType?: 'standalone' | 'parent' | 'child';
  parentArticleId?: string;
  childArticles?: Article[];
}

export interface Activity {
  id: string;
  universeId: string;
  title: string;
  category: string;
  price: string;
  image: string;
  description: string;
  minAdvanceDays?: number;
  hasArticles?: boolean;
  articleDisplayType?: 'direct' | 'articles_only';
  articles?: Article[];
  isFeatured?: boolean;
  featuredDisplayType?: 'card' | 'hero' | 'grid' | 'carousel';
  featuredOrder?: number;
  featuredImageUrl?: string;
  /** Présent quand l’activité est chargée depuis la base (tri, admin). */
  created_at?: string;
}

export interface Product {
  id: string;
  title: string;
  category: string;
  price: number;
  oldPrice?: number;
  image: string;
  description: string;
  isExclusive?: boolean;
}

export interface JournalPost {
  id: string;
  title: string;
  category: string;
  date: string;
  image: string;
  excerpt: string;
  content: string;
}

export interface Testimonial {
  id: string;
  name: string;
  role: string;
  content: string;
  rating: number;
  image?: string;
  isApproved: boolean;
}

export interface NewsletterSubscriber {
  id: string;
  email: string;
  subscribedAt: string;
}

export type { SiteSettings };

export interface Profile {
  id: string;
  full_name: string;
  email: string;
  role: string;
  avatar_url?: string;
  created_at: string;
}

export interface Ticket {
  id: string;
  user_name: string;
  user_email: string;
  subject: string;
  status: 'open' | 'closed';
  created_at: string;
}

export interface TicketMessage {
  id: string;
  ticket_id: string;
  sender: string;
  content: string;
  created_at: string;
}

export interface GlobalService {
  id: string;
  title: string;
  description: string;
  image: string;
  link: string;
  type?: string; // Categorie: restaurant, shop, activity, etc.
  latitude?: number;
  longitude?: number;
}

export interface Order {
  id: string;
  customer_name: string;
  customer_email: string;
  total: number;
  items: any[];
  receipt_base64?: string;
  user_phone?: string;
  country?: string;
  phone_code?: string;
  status: 'pending' | 'completed' | 'cancelled';
  created_at: string;
}

export type Theme = 'light' | 'dark';

interface AppContextType {
  reservations: Reservation[];
  addReservation: (reservation: Omit<Reservation, 'id' | 'created_at' | 'status'>) => Promise<void>;
  updateReservationStatus: (id: string, status: Reservation['status']) => Promise<void>;
  deleteReservation: (id: string) => Promise<void>;

  orders: Order[];
  addOrder: (order: Omit<Order, 'id' | 'created_at' | 'status'>) => Promise<void>;
  updateOrderStatus: (id: string, status: Order['status']) => Promise<void>;
  deleteOrder: (id: string) => Promise<void>;

  tickets: Ticket[];
  refreshTickets: () => Promise<void>;
  addTicket: (ticket: Omit<Ticket, 'id' | 'created_at' | 'status'>) => Promise<string>;
  updateTicketStatus: (id: string, status: Ticket['status']) => Promise<void>;
  deleteTicket: (id: string) => Promise<void>;

  ticketMessages: TicketMessage[];
  addTicketMessage: (message: Omit<TicketMessage, 'id' | 'created_at'>) => Promise<void>;
  fetchTicketMessages: (ticketId: string) => Promise<TicketMessage[]>;

  universes: Universe[];
  addUniverse: (u: Universe) => void;
  updateUniverse: (u: Universe) => void;
  deleteUniverse: (id: string) => void;

  activities: Activity[];
  addActivity: (a: Activity) => void;
  updateActivity: (a: Activity) => void;
  deleteActivity: (id: string) => void;

  articles: Article[];
  addArticle: (a: Article) => void;
  updateArticle: (a: Article) => void;
  deleteArticle: (id: string) => void;
  getArticlesByActivityId: (activityId: string) => Article[];
  refreshArticles: () => void;

  products: Product[];
  addProduct: (p: Product) => void;
  updateProduct: (p: Product) => void;
  deleteProduct: (id: string) => void;

  journalPosts: JournalPost[];
  addJournalPost: (p: JournalPost) => void;
  updateJournalPost: (p: JournalPost) => void;
  deleteJournalPost: (id: string) => void;

  testimonials: Testimonial[];
  addTestimonial: (t: Omit<Testimonial, 'id' | 'isApproved'>) => void;
  updateTestimonial: (t: Testimonial) => void;
  deleteTestimonial: (id: string) => void;

  globalServices: GlobalService[];
  addGlobalService: (s: GlobalService) => void;
  updateGlobalService: (s: GlobalService) => void;
  deleteGlobalService: (id: string) => void;

  subscribers: NewsletterSubscriber[];
  subscribeNewsletter: (email: string) => Promise<boolean>;
  unsubscribeNewsletter: (id: string) => Promise<void>;
  refreshNewsletterSubscribers: () => Promise<void>;

  settings: SiteSettings;
  updateSettings: (s: SiteSettings) => void;

  currency: Currency;
  setCurrency: (currency: Currency) => void;
  exchangeRates: ExchangeRates;
  refreshExchangeRates: () => Promise<void>;

  searchQuery: string;
  setSearchQuery: (q: string) => void;

  profiles: Profile[];
  deleteProfile: (id: string) => void;

  theme: Theme;
  toggleTheme: () => void;

  language: Language;
  setLanguage: (lang: Language) => void;
}

