const isVideoUrl = (url: string): boolean => {
  if (!url) return false;
  const normalizedUrl = url.toLowerCase();
  return (
    normalizedUrl.includes("youtube.com") ||
    normalizedUrl.includes("youtu.be") ||
    normalizedUrl.includes("vimeo.com") ||
    normalizedUrl.includes(".mp4") ||
    normalizedUrl.includes(".webm") ||
    normalizedUrl.includes(".mov") ||
    normalizedUrl.includes(".avi")
  );
};

const isYouTubeUrl = (url: string): boolean => {
  if (!url) return false;
  const normalizedUrl = url.toLowerCase();
  return normalizedUrl.includes("youtube.com") || normalizedUrl.includes("youtu.be");
};

const getYouTubeEmbedUrl = (url: string): string => {
  const videoIdMatch =
    url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/)([a-zA-Z0-9_-]+)/) ||
    url.match(/([a-zA-Z0-9_-]{11})/);
  return videoIdMatch ? `https://www.youtube.com/embed/${videoIdMatch[1]}?autoplay=1&mute=1&controls=0&modestbranding=1` : "";
};

type TabType = "general" | "about" | "design" | "bank" | "security";

type StringListProps = {
  items: string[];
  onChange: (next: string[]) => void;
  placeholder?: string;
  addLabel: string;
  inputClassName?: string;
};

function StringListEditor({ items, onChange, placeholder, addLabel, inputClassName }: StringListProps) {
  const inputCls = inputClassName ?? "admin-input min-h-[2.75rem] flex-1 py-3 px-4 text-sm";
  const update = (i: number, v: string) => {
    const next = [...items];
    next[i] = v;
    onChange(next);
  };
  const remove = (i: number) => onChange(items.filter((_, j) => j !== i));
  const add = () => onChange([...items, ""]);
  return (
    <div className="space-y-2.5">
      {items.map((v, i) => (
        <div key={i} className="flex items-center gap-2.5">
          <input
            type="text"
            value={v}
            onChange={(e) => update(i, e.target.value)}
            placeholder={placeholder}
            className={inputCls}
          />
          <button
            type="button"
            onClick={() => remove(i)}
            className="shrink-0 rounded-lg p-3 text-text-primary/35 transition-colors hover:bg-red-500/10 hover:text-red-400 touch-manipulation"
            aria-label="Supprimer la ligne"
          >
            <Trash2 size={16} aria-hidden />
          </button>
        </div>
      ))}
      <button
        type="button"
        onClick={add}
        className="inline-flex min-h-11 items-center gap-2 rounded-lg border border-border-primary/50 px-3.5 py-2 text-[10px] font-bold uppercase tracking-widest text-text-primary/50 transition-colors hover:border-brand-gold/35 hover:text-brand-gold touch-manipulation"
      >
        <Plus size={14} aria-hidden />
        {addLabel}
      </button>
    </div>
  );
}

type ContactEmailListProps = {
  items: ContactEmailItem[];
  onChange: (next: ContactEmailItem[]) => void;
  labelPlaceholder?: string;
  emailPlaceholder?: string;
  addLabel: string;
};

function ContactEmailListEditor({
  items,
  onChange,
  labelPlaceholder = "Ex. Réservations",
  emailPlaceholder = "email@casaprivilege.com",
  addLabel,
}: ContactEmailListProps) {
  const update = (i: number, key: keyof ContactEmailItem, value: string) => {
    const next = [...items];
    next[i] = { ...next[i], [key]: value };
    onChange(next);
  };
  const remove = (i: number) => onChange(items.filter((_, j) => j !== i));
  const add = () => onChange([...items, { label: "", email: "" }]);

  return (
    <div className="space-y-3">
      {items.map((entry, i) => (
        <div key={i} className="grid grid-cols-1 gap-2.5 md:grid-cols-[1fr_1.25fr_auto]">
          <input
            type="text"
            value={entry.label}
            onChange={(e) => update(i, "label", e.target.value)}
            placeholder={labelPlaceholder}
            className="admin-input min-h-[2.75rem] flex-1 py-3 px-4 text-sm"
          />
          <input
            type="email"
            value={entry.email}
            onChange={(e) => update(i, "email", e.target.value)}
            placeholder={emailPlaceholder}
            className="admin-input min-h-[2.75rem] flex-1 py-3 px-4 text-sm"
          />
          <button
            type="button"
            onClick={() => remove(i)}
            className="shrink-0 rounded-lg p-3 text-text-primary/35 transition-colors hover:bg-red-500/10 hover:text-red-400 touch-manipulation md:self-stretch"
            aria-label="Supprimer l'email"
          >
            <Trash2 size={16} aria-hidden />
          </button>
        </div>
      ))}
      <button
        type="button"
        onClick={add}
        className="inline-flex min-h-11 items-center gap-2 rounded-lg border border-border-primary/50 px-3.5 py-2 text-[10px] font-bold uppercase tracking-widest text-text-primary/50 transition-colors hover:border-brand-gold/35 hover:text-brand-gold touch-manipulation"
      >
        <Plus size={14} aria-hidden />
        {addLabel}
      </button>
    </div>
  );
}

export function SettingsView() {
  const { settings, updateSettings, language } = useAppContext();
  const [formData, setFormData] = useState(settings);
  const [activeTab, setActiveTab] = useState<TabType>("general");
  const [saved, setSaved] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [rememberWorkspace, setRememberWorkspace] = useState<boolean>(() => {
    if (typeof window === "undefined") return true;
    return localStorage.getItem("cp:remember-work") !== "0";
  });

  const location = useLocation();

  useEffect(() => {
    setFormData(settings);
  }, [settings]);

  useEffect(() => {
    if (location.pathname.endsWith("/about")) {
      setActiveTab("about");
    }
  }, [location.pathname]);

  const handleSubmit = () => {
    void updateSettings(formData);
    setSaved(true);
    window.setTimeout(() => setSaved(false), 3000);
  };

  const handleToggleRememberWorkspace = () => {
    const next = !rememberWorkspace;
    setRememberWorkspace(next);
    localStorage.setItem("cp:remember-work", next ? "1" : "0");
  };

  const currentHeroBgUrl = formData.heroBackgroundUrl?.trim() || "";
  const isHeroYouTube = isYouTubeUrl(currentHeroBgUrl);
  const heroYouTubeEmbedUrl = isHeroYouTube ? getYouTubeEmbedUrl(currentHeroBgUrl) : "";
  const isHeroVimeo = currentHeroBgUrl.includes("vimeo.com");
  const isHeroDirectVideo = currentHeroBgUrl.includes(".mp4") || currentHeroBgUrl.includes(".webm") || currentHeroBgUrl.includes(".mov");

  const tabs: { id: TabType; label: string; icon: LucideIcon }[] = [
    { id: "general", label: "Informations", icon: Globe },
    { id: "about", label: "About Us", icon: LayoutIcon },
    { id: "design", label: "Design & apparence", icon: Palette },
    { id: "bank", label: "Gestion RIB", icon: CreditCard },
